// Canh gác app từ PHÍA n8n — nửa còn lại của bộ canh gác hai chiều.
//
// App canh n8n (nhịp tim quá hạn -> chuông). Nhưng khi chính app chết thì chuông cũng chết,
// không ai biết. Workflow này chạy trong n8n, độc lập với app: app không trả lời -> email.
// Hai bên canh nhau; muốn cả hệ thống im lặng thì phải chết cả hai cùng lúc.
//
// Chống spam: app sập 5 giờ không được thành 10 email. Nhớ trạng thái bằng static data của
// workflow (chỉ lưu khi chạy thật theo lịch, không lưu khi bấm Execute thử):
//   - lần đầu thấy hỏng -> báo; hỏng tiếp -> nhắc lại mỗi 3 giờ.
//   - thấy khoẻ lại sau khi đã hỏng -> báo "đã hoạt động lại" kèm thời gian gián đoạn.
//     Đó là bước KHÉP vòng: người nhận không phải tự đi kiểm tra xem đã xong chưa.
const r = $json;
const code = r.statusCode ?? 0;
const body = (r.body && typeof r.body === 'object') ? r.body : {};
const status = body.status ?? (r.error ? 'unreachable' : 'unknown');
const healthy = code === 200 && status === 'ok';

const state = $getWorkflowStaticData('global');
const now = Date.now();
const REMIND_MS = 3 * 60 * 60 * 1000;
const fmt = (ms) => { const m = Math.round(ms / 60000); if (m < 60) return m + ' phút'; const h = Math.floor(m / 60), r = m % 60; return h + ' giờ' + (r ? ' ' + r + ' phút' : ''); };

let send = false, subject = '', html = '';
const problems = Array.isArray(body.checks) ? body.checks.filter(c => !c.ok).map(c => '<li>' + c.name + ': ' + c.detail + '</li>').join('') : '';

if (!healthy) {
  if (!state.downSince) state.downSince = now;
  if (!state.lastAlertAt || now - state.lastAlertAt > REMIND_MS) {
    send = true;
    const first = !state.lastAlertAt;
    state.lastAlertAt = now;
    subject = (status === 'degraded' ? '🟠 ANSER Auto: vòng tự động đang hỏng' : '🔴 ANSER Auto không phản hồi')
      + (first ? '' : ' (nhắc lại)');
    html = '<p>Trạng thái: <b>' + status + '</b> (HTTP ' + (code || 'không kết nối được') + ').</p>'
      + (problems ? '<ul>' + problems + '</ul>' : '')
      + '<p>Bắt đầu từ ' + new Date(state.downSince).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })
      + ' — đã ' + fmt(now - state.downSince) + '. Sẽ nhắc lại mỗi 3 giờ và báo khi hoạt động lại.</p>';
  }
} else if (state.downSince) {
  send = true;
  subject = '🟢 ANSER Auto đã hoạt động lại';
  html = '<p>Gián đoạn ' + fmt(now - state.downSince) + ', kết thúc lúc '
    + new Date(now).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) + '.</p>';
  state.downSince = null;
  state.lastAlertAt = null;
}

return [{ json: { send, email_to: 'REPLACE_WITH_ALERT_EMAIL', subject, html, status, http: code } }];
